package forth

import (
	"errors"
	"strconv"
	"strings"
)

// instruction kinds
const (
	kindNum = iota // push a number
	kindOp         // perform a built-in operation (name holds the op)
	kindWord       // reference to a user-defined word (name holds the word);
	// resolved lazily at execution time
)

// instr is a single step of a definition body or of execution.
type instr struct {
	kind int
	num  int    // used when kind == kindNum
	name string // used when kind == kindOp or kindWord (lower-cased)
}

// Forth evaluates a sequence of Forth source lines and returns the resulting
// value stack. A non-nil error is returned when evaluation fails.
func Forth(input []string) ([]int, error) {
	dict := make(map[string][]instr) // user-defined words, keyed by lower-cased name
	stack := []int{}

	for _, line := range input {
		tokens := strings.Fields(line)
		i := 0
		for i < len(tokens) {
			if tokens[i] == ":" {
				// A word definition: : name body... ;
				i++
				if i >= len(tokens) {
					return nil, errors.New("malformed definition: missing word name")
				}
				name := strings.ToLower(tokens[i])
				i++
				if isNumber(name) {
					return nil, errors.New("cannot redefine a number")
				}
				var body []instr
				for i < len(tokens) {
					if tokens[i] == ";" {
						i++
						break
					}
					body = append(body, expandToken(tokens[i], dict)...)
					i++
				}
				dict[name] = body
				continue
			}

			body := expandToken(tokens[i], dict)
			if err := exec(body, dict, &stack); err != nil {
				return nil, err
			}
			i++
		}
	}
	return stack, nil
}

// expandToken turns a single token into one or more instructions. User-defined
// words are inlined (their body is spliced in) at definition time so that a
// word captures the definitions that existed when it was defined.
func expandToken(token string, dict map[string][]instr) []instr {
	t := strings.ToLower(token)
	if isNumber(t) {
		n, _ := strconv.Atoi(t)
		return []instr{{kind: kindNum, num: n}}
	}
	// User-defined words take precedence over built-ins (they can override them).
	if def, ok := dict[t]; ok {
		return def
	}
	if isBuiltin(t) {
		return []instr{{kind: kindOp, name: t}}
	}
	return []instr{{kind: kindWord, name: t}} // undefined; resolved at execution
}

// exec runs a list of instructions against the stack.
func exec(body []instr, dict map[string][]instr, stack *[]int) error {
	for _, ins := range body {
		switch ins.kind {
		case kindNum:
			*stack = append(*stack, ins.num)
		case kindOp:
			if err := applyOp(ins.name, stack); err != nil {
				return err
			}
		case kindWord:
			def, ok := dict[ins.name]
			if !ok {
				return errors.New("undefined operation: " + ins.name)
			}
			if err := exec(def, dict, stack); err != nil {
				return err
			}
		}
	}
	return nil
}

// applyOp performs a built-in stack operation.
func applyOp(op string, stack *[]int) error {
	n := len(*stack)
	switch op {
	case "+", "-", "*", "/":
		if n < 2 {
			return errors.New("stack underflow")
		}
		b := (*stack)[n-1]
		a := (*stack)[n-2]
		*stack = (*stack)[:n-2]
		switch op {
		case "+":
			*stack = append(*stack, a+b)
		case "-":
			*stack = append(*stack, a-b)
		case "*":
			*stack = append(*stack, a*b)
		case "/":
			if b == 0 {
				return errors.New("division by zero")
			}
			*stack = append(*stack, a/b)
		}
	case "dup":
		if n < 1 {
			return errors.New("stack underflow")
		}
		*stack = append(*stack, (*stack)[n-1])
	case "drop":
		if n < 1 {
			return errors.New("stack underflow")
		}
		*stack = (*stack)[:n-1]
	case "swap":
		if n < 2 {
			return errors.New("stack underflow")
		}
		(*stack)[n-1], (*stack)[n-2] = (*stack)[n-2], (*stack)[n-1]
	case "over":
		if n < 2 {
			return errors.New("stack underflow")
		}
		*stack = append(*stack, (*stack)[n-2])
	default:
		return errors.New("unknown operation: " + op)
	}
	return nil
}

// isNumber reports whether s is an integer literal (optionally signed).
// A lone "-" is not a number; it is the subtraction operator.
func isNumber(s string) bool {
	if s == "" {
		return false
	}
	start := 0
	if s[0] == '-' {
		start = 1
	}
	if start >= len(s) {
		return false
	}
	for i := start; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// isBuiltin reports whether s (already lower-cased) is a built-in word.
func isBuiltin(s string) bool {
	switch s {
	case "+", "-", "*", "/", "dup", "drop", "swap", "over":
		return true
	}
	return false
}

